#!/usr/bin/env python3
# Writes src/gfm2026.html (version A: our stand) and src/gfm2026-tins.html (version B: our tins) from one layout,
# so the two versions never drift. Then: node content/social/gfm-2026/render.mjs
import os
HERE = os.path.dirname(os.path.abspath(__file__))

HEAD = '''<!doctype html>
<html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>%s</title>
<link rel="stylesheet" href="brand.css">
<link rel="stylesheet" href="gfm.css">
</head>
<body>
<!-- Generated by build-cards.py. %s -->
'''
SCRIPT = '''
<script>
// Stand number in one place: ?stand=... in the URL (render.mjs passes it), default CC1-190.
const stand = new URLSearchParams(location.search).get('stand') || 'CC1-190';
document.querySelectorAll('.standno').forEach((el) => { el.textContent = stand; });
</script>
</body></html>
'''
FRAME = '<div class="frame-line" style="inset:40px"></div>'
LOGO = '<img class="ourlogo" src="assets/logo-h-white.svg" alt="Jordan Tinplate Canning" style="height:%dpx">'
PILL = '<span class="pill"><span>الجناح</span><b class="standno">CC1-190</b></span>'
EYE = '<p class="eyebrow" style="%s">دعوة خاصة لزيارة جناحنا في دبي</p>'
H1 = '<h1 class="ar" style="font-size:%dpx;margin-top:%dpx">صُنع في الأردن،%sويُعرض في دبي</h1>'
H2 = '<h2 class="en" style="font-size:%dpx;margin-top:%dpx;align-self:stretch;text-align:right">Crafted in Jordan. Presented in Dubai.</h2>'
LEAD = '<p class="lead" style="font-size:%dpx;margin-top:%dpx;max-width:%dpx">تتشرّف <b>الشركة الأردنية لصناعة وطباعة الصفيح والعبوات المعدنية</b> بدعوتكم لزيارة جناحها في معرض Gulfood Manufacturing 2026 في دبي.</p>'
GFM = '<img class="gfm" src="assets/gfm-2026-logo.png" alt="Gulfood Manufacturing, 3–5 November 2026, Dubai World Trade Centre" style="height:%dpx">'
MAIL = '<div style="display:flex;flex-direction:column;gap:4px;align-items:%s"><span class="small">لحجز موعد</span><span class="mail" style="font-size:%dpx">sales@jordantinplate.com</span></div>'
QR = '<div style="display:flex;align-items:center;gap:12px"><span class="small" style="text-align:left">امسح لزيارة<br>الموقع</span><span class="q" style="width:%dpx;height:%dpx"><img src="assets/qr-website.svg" alt="QR code to jordantinplate.com"></span></div>'


def page(prefix, title, note, hero):
    post = f'''
<!-- ======================================================= POST 1080 x 1350 -->
<div class="frame inv" data-name="{prefix}-post-1080x1350" style="width:1080px;height:1350px">
  {FRAME}
  <div class="box" style="top:96px;left:96px;right:96px;height:60px;flex-direction:row;align-items:center;justify-content:space-between">{LOGO % 56}{PILL}</div>
  <div class="box" style="top:204px;left:96px;right:96px;align-items:flex-start">{hero('post')}</div>
  <div class="box" style="top:850px;bottom:96px;left:96px;right:96px;align-items:flex-start">
    {EYE % ''}
    {H1 % (56, 10, ' ')}
    {H2 % (26, 12)}
    {LEAD % (19, 18, 860)}
    <div style="margin-top:auto;align-self:stretch;display:flex;flex-direction:column;gap:24px">
      <div class="hair"></div>
      <div style="display:flex;align-items:center;justify-content:space-between">
        {GFM % 60}
        {MAIL % ('flex-end', 22)}
        {QR % (68, 68)}
      </div>
    </div>
  </div>
</div>
'''
    story = f'''
<!-- ======================================================= STORY 1080 x 1920 (Stories UI: content between 220 px from the top and 300 px from the bottom) -->
<div class="frame inv" data-name="{prefix}-story-1080x1920" style="width:1080px;height:1920px">
  {FRAME}
  <div class="box" style="top:220px;left:96px;right:96px;height:64px;flex-direction:row;align-items:center;justify-content:space-between">{LOGO % 60}{PILL}</div>
  <div class="box" style="top:340px;left:96px;right:96px;align-items:flex-start">
    {EYE % ''}
    {H1 % (66, 10, '<br>')}
    {H2 % (30, 14)}
  </div>
  <div class="box" style="top:720px;left:96px;right:96px;align-items:flex-start">{hero('story')}</div>
  <div class="box" style="top:1340px;bottom:300px;left:96px;right:96px;align-items:flex-start;justify-content:flex-end">
    <div style="align-self:stretch;display:flex;flex-direction:column;gap:26px">
      <div class="hair"></div>
      <div style="display:flex;align-items:center;justify-content:space-between">
        {GFM % 66}
        {MAIL % ('flex-end', 23)}
      </div>
    </div>
  </div>
</div>
'''
    banner = f'''
<!-- ======================================================= BANNER 1920 x 1080 (words on the right, Arabic first; the visual on the left) -->
<div class="frame inv" data-name="{prefix}-banner-1920x1080" style="width:1920px;height:1080px;background:radial-gradient(45% 70% at 72% 0%, #0d4489 0%, #002F6C 48%, #001a44 100%)">
  {FRAME}
  <div class="box" style="top:104px;bottom:104px;right:120px;width:800px;align-items:flex-start">
    <div style="align-self:stretch;display:flex;align-items:center;justify-content:space-between">{LOGO % 56}{PILL}</div>
    {EYE % 'margin-top:64px'}
    {H1 % (62, 10, '<br>')}
    {H2 % (30, 14)}
    {LEAD % (20, 26, 720)}
    <div style="margin-top:auto;align-self:stretch;display:flex;flex-direction:column;gap:22px">
      <div class="hair"></div>
      <div style="display:flex;align-items:center;justify-content:space-between;gap:28px">{GFM % 62}{MAIL % ('flex-end', 21)}<span class="q" style="width:68px;height:68px"><img src="assets/qr-website.svg" alt="QR code to jordantinplate.com"></span></div>
    </div>
  </div>
  <div class="box" style="top:104px;bottom:104px;left:120px;width:900px;align-items:center;justify-content:center">
    {hero('banner')}
  </div>
</div>
'''
    return HEAD % (title, note) + post + story + banner + SCRIPT


def gallery(w, h, img, pos):
    return f'<div class="gallery" style="width:{w}px;height:{h}px"><img src="assets/{img}" alt="جناح الشركة في Gulfood Manufacturing 2026" style="object-position:{pos}"></div>'


def booth(fmt):
    if fmt == 'post':
        return gallery(888, 600, 'booth-cine.jpg', '50% 66%')
    if fmt == 'story':
        return gallery(888, 580, 'booth-cine.jpg', '50% 66%')
    return gallery(900, 700, 'booth-cine.jpg', '42% 62%')


# tins: (name, left, width, z-index, extra lift)
POST_TINS = [('abu-salha', 20, 160, 1, 8), ('maamoul-walnut', 90, 270, 3, 0), ('malka-16l', 340, 270, 2, 0), ('souf-ategah', 650, 230, 1, 8), ('givinova', 600, 250, 3, 0)]
BANNER_TINS = [('abu-salha', 10, 175, 1, 8), ('maamoul-walnut', 90, 300, 3, 0), ('malka-16l', 360, 300, 2, 0), ('maamoul-dates', 620, 250, 2, 6), ('givinova', 650, 250, 3, 0)]


def tin(name, left, w, z, lift):
    return f'<div class="tin" style="left:{left}px;width:{w}px;z-index:{z};margin-bottom:{lift}px"><img src="assets/tins/{name}.png" alt=""><img class="rf" src="assets/tins/{name}.png" alt=""></div>'


def stage(w, h, fl, items, scale=1.0):
    tins = ''.join(tin(n, round(l * scale), round(ww * scale), z, lift) for n, l, ww, z, lift in items)
    return f'<div class="stage" style="width:{w}px;height:{h}px;--fl:{fl}px"><div class="halo"></div>{tins}<div class="shade"></div><div class="plinth"></div></div>'


def tins(fmt):
    if fmt == 'post':
        return stage(888, 600, 100, POST_TINS, 1.1)
    if fmt == 'story':
        return stage(888, 600, 110, POST_TINS, 1.08)
    return stage(900, 720, 130, BANNER_TINS, 1.0)


with open(os.path.join(HERE, 'src', 'gfm2026.html'), 'w') as f:
    f.write(page('gfm2026', 'GFM 2026 invitation, our stand', 'Version A: the 3D render of our Dubai booth (assets/booth-cine.jpg, our section only) as a crisp gallery photo.', booth))
with open(os.path.join(HERE, 'src', 'gfm2026-tins.html'), 'w') as f:
    f.write(page('gfm2026-tins', 'GFM 2026 invitation, our tins', 'Version B: our tins, cut out of the photoshoot board photos, on a lit plinth with reflections.', tins))
print('wrote src/gfm2026.html, src/gfm2026-tins.html')
